ALTER TABLE "Product" ADD COLUMN "stockOnHand" INTEGER, ADD COLUMN "stockReserved" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "stockVersion" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "stockWarning" INTEGER NOT NULL DEFAULT 0;
ALTER TABLE "Product" ADD CONSTRAINT "Product_stock_check" CHECK (("stockOnHand" IS NULL AND "stockReserved" = 0) OR ("stockOnHand" >= "stockReserved" AND "stockReserved" >= 0));
ALTER TABLE "Product" ADD CONSTRAINT "Product_stock_warning_check" CHECK ("stockWarning" >= 0);
CREATE TABLE "ProductStockHold" ("id" TEXT PRIMARY KEY, "orderId" TEXT NOT NULL, "productId" TEXT NOT NULL REFERENCES "Product"("id") ON DELETE RESTRICT, "quantity" INTEGER NOT NULL CHECK ("quantity" > 0), "status" TEXT NOT NULL DEFAULT 'RESERVED' CHECK ("status" IN ('RESERVED','RELEASED','CONSUMED','REFUNDED')), UNIQUE ("orderId", "productId"));
CREATE TABLE "ProductStockMovement" ("id" TEXT PRIMARY KEY, "productId" TEXT NOT NULL REFERENCES "Product"("id") ON DELETE RESTRICT, "orderId" TEXT, "actorId" TEXT NOT NULL, "reason" TEXT NOT NULL, "kind" TEXT NOT NULL, "beforeOnHand" INTEGER, "afterOnHand" INTEGER NOT NULL, "beforeReserved" INTEGER NOT NULL, "afterReserved" INTEGER NOT NULL, "requestId" TEXT UNIQUE, "requestHash" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "ProductStockMovement_productId_createdAt_idx" ON "ProductStockMovement"("productId", "createdAt");
